    ray=next(v for v in counts if v not in (bg,border))
    # Every other cell of each edge segment (starting just inside the segment)
    # emits a ray perpendicular to that edge.
    for side in ('L','R','T','B'):
        n=h if side in ('L','R') else w
        def edge(i):
            return g[i][0] if side=='L' else g[i][w-1] if side=='R' else g[0][i] if side=='T' else g[h-1][i]
        i=0
