                i+=1; continue
            j=i
            while j+1<n and edge(j+1)==border: j+=1
            for k in range(i+1,j+1,2):
                if side=='L': coords=[(k,c) for c in range(1,w)]
                elif side=='R': coords=[(k,c) for c in range(w-2,-1,-1)]
                elif side=='T': coords=[(r,k) for r in range(1,h)]
                else: coords=[(r,k) for r in range(h-2,-1,-1)]
                for r,c in coords:
                    if g[r][c]==ray:
                        g[r][c]=4; break
                    if g[r][c]==bg: g[r][c]=ray
                    elif g[r][c]==border: break
            i=j+1
    # A marker lying on the row/column of an edge segment is reached by that ray.
    for r in range(h):
        for c in range(w):
