            dirs=[]
            if g[r][0]==border: dirs.append(('L', c))
            if g[r][w-1]==border: dirs.append(('R', w-1-c))
            if g[0][c]==border: dirs.append(('T', r))
            if g[h-1][c]==border: dirs.append(('B', h-1-r))
            if not dirs: continue
            d=min(dirs,key=lambda x:x[1])[0]
            g[r][c]=4
            if d=='L': coords=[(r,x) for x in range(c-1,-1,-1)]
            elif d=='R': coords=[(r,x) for x in range(c+1,w)]
