    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    border = next(grid[r][c] for r in range(h) for c in range(w)
                  if grid[r][c] != bg and (r == 0 or r == h-1 or c == 0 or c == w-1))
    ray = next(v for v in counts if v not in (bg, border))

    # Find contiguous runs of border color along each edge.
    runs = {s: [] for s in ('L', 'R', 'T', 'B')}
    for side in runs:
        n = h if side in ('L', 'R') else w
        def edge_value(i):
            if side == 'L': return grid[i][0]
            if side == 'R': return grid[i][w-1]
            if side == 'T': return grid[0][i]
            return grid[h-1][i]
        i = 0
        while i < n:
            if edge_value(i) != border:
                i += 1
                continue
            j = i
            while j + 1 < n and edge_value(j+1) == border:
                j += 1
            runs[side].append((i, j))
            i = j + 1

    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == ray]
    pairs = {'L': 'R', 'R': 'L', 'T': 'B', 'B': 'T'}

    for r, c in markers:
        # A marker whose row/column lies within an edge run projects to that edge.
        candidates = []
        for side, pos in (('L', r), ('R', r), ('T', c), ('B', c)):
            for a, b in runs[side]:
                if a <= pos <= b:
                    # marker is projected toward its aligned edge segment
                    if side == 'L': dist = c
                    elif side == 'R': dist = w - 1 - c
                    elif side == 'T': dist = r
                    else: dist = h - 1 - r
                    candidates.append((dist, side, a, b, pos))
        if not candidates:
            continue
        _, side, a, b, pos = min(candidates)
        out[r][c] = 4

        # Ray from the marker toward the edge segment it aligns with.
        if side == 'L': path = [(r, x) for x in range(c-1, -1, -1)]
        elif side == 'R': path = [(r, x) for x in range(c+1, w)]
        elif side == 'T': path = [(y, c) for y in range(r-1, -1, -1)]
        else: path = [(y, c) for y in range(r+1, h)]
        for y, x in path:
            if grid[y][x] == border:
                break
            if grid[y][x] == bg:
                out[y][x] = ray

        # The equal-length run on the opposite edge emits a corresponding
        # ray at the same offset along the run.
        opposite = pairs[side]
        paired_run = next(((u, v) for u, v in runs[opposite] if v-u == b-a), None)
        if paired_run is None:
            continue
        k = paired_run[0] + (pos - a)
        if side in ('L', 'R'):
            line = [(k, x) for x in range(1, w-1)]
        else:
            line = [(y, k) for y in range(1, h-1)]
        for y, x in line:
            if (y, x) == (r, c):
                out[y][x] = 4
            elif grid[y][x] == ray:
                out[y][x] = 4
            else:
                out[y][x] = ray
    return out
